DROP TABLE IF EXISTS gv_vem; CREATE TABLE gv_vem ( sequence integer  NULL, plot integer  NULL, sample_id smallint  NULL, survey_nr smallint  NULL, species character varying(11)  NULL, layer smallint  NULL, substrate smallint  NULL, species_cover numeric  NULL, certainty smallint  NULL, other_observations character varying  NULL, CONSTRAINT tmp_gv_vem_2011_pk     PRIMARY KEY (country_code, partner_code, survey_year, line_nr));
